raw.css:
:root {
  --color-bg: #ffffff;
  --color-bg-alt: #f7f3ef;
  --color-text: #2b2420;
  --color-text-muted: #5a5048;
  --color-accent: #8a4b2b;
  --color-accent-dark: #6e3b20;
  --color-accent-on-dark: #e8c9a0;
  --color-dark-bg: #231d1a;
  --color-border: #ddd3c8;
  --font-body: Georgia, 'Times New Roman', serif;
  --font-heading: 'Palatino Linotype', 'Book Antiqua', Georgia, serif;
  --spacing-sm: 0.5rem;
  --spacing-md: 1rem;
  --spacing-lg: 2rem;
  --spacing-xl: 4rem;
  --radius: 0.4rem;
  --max-width: 75rem;
}

*, *::before, *::after { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  font-family: var(--font-body);
  color: var(--color-text);
  background-color: var(--color-bg);
  line-height: 1.6;
  font-size: 1rem;
}

h1, h2, h3, h4 {
  font-family: var(--font-heading);
  color: var(--color-text);
  line-height: 1.25;
  margin-top: 0;
}

p { margin-top: 0; }

a {
  color: var(--color-accent-dark);
  text-decoration: underline;
}

a:hover { color: var(--color-accent); }

a:focus-visible, button:focus-visible, input:focus-visible, textarea:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

img { max-width: 100%; display: block; }

.container {
  width: 100%;
  max-width: var(--max-width);
  margin-left: auto;
  margin-right: auto;
  padding-left: 1.25rem;
  padding-right: 1.25rem;
}

/* Header */
header {
  background-color: var(--color-bg-alt);
  border-bottom: 1px solid var(--color-border);
}

.header-inner {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--spacing-md);
  padding-top: var(--spacing-md);
  padding-bottom: var(--spacing-md);
}

.logo {
  font-family: 'Palatino Linotype', 'Book Antiqua', Georgia, serif;
  font-variant: small-caps;
  font-weight: 400;
  letter-spacing: 0.25em;
  font-size: clamp(1.1rem, 2.5vw, 1.6rem);
  color: var(--color-accent-dark);
  text-decoration: none;
  border-bottom: 1px solid var(--color-accent-dark);
  width: fit-content;
  padding-bottom: 0.2rem;
}

.logo:hover { color: var(--color-accent); border-color: var(--color-accent); }

nav .nav-list {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: var(--spacing-md);
  margin: 0;
  padding: 0;
}

nav .nav-list a {
  text-decoration: none;
  color: var(--color-text);
  font-size: 0.95rem;
  padding: 0.4rem 0.2rem;
}

nav .nav-list a:hover {
  color: var(--color-accent-dark);
  text-decoration: underline;
}

/* Footer */
footer {
  background-color: var(--color-dark-bg);
  color: var(--color-accent-on-dark);
  padding: var(--spacing-lg) 0;
  margin-top: var(--spacing-xl);
}

footer p { margin: 0.25rem 0; font-size: 0.95rem; }

.footer-brand {
  font-family: var(--font-heading);
  font-variant: small-caps;
  letter-spacing: 0.15em;
  font-size: 1.1rem;
  color: var(--color-accent-on-dark);
  margin-bottom: var(--spacing-sm);
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: 0.75rem 1.5rem;
  background-color: var(--color-accent-dark);
  color: #ffffff;
  border: none;
  border-radius: var(--radius);
  font-size: 1rem;
  font-family: var(--font-body);
  text-decoration: none;
  cursor: pointer;
}

.btn:hover { background-color: var(--color-accent); }

.btn:focus-visible { outline: 3px solid var(--color-text); outline-offset: 2px; }

/* Cards */
.card {
  background-color: var(--color-bg-alt);
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  padding: var(--spacing-lg);
}

/* Grid helper */
.grid {
  display: grid;
  gap: var(--spacing-lg);
  grid-template-columns: 1fr;
}

/* Forms */
form {
  display: grid;
  gap: var(--spacing-md);
  max-width: 40rem;
}

.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

label {
  font-weight: bold;
  font-size: 0.95rem;
  color: var(--color-text);
}

input, textarea, select {
  font-family: var(--font-body);
  font-size: 1rem;
  padding: 0.65rem 0.75rem;
  min-height: 44px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  background-color: var(--color-bg);
  color: var(--color-text);
}

textarea { min-height: 8rem; resize: vertical; }

input:focus, textarea:focus, select:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 1px;
}

section {
  padding-top: var(--spacing-xl);
  padding-bottom: var(--spacing-xl);
}

/* Mobile breakpoint */
@media (max-width: 600px) {
  .header-inner {
    flex-direction: column;
    align-items: flex-start;
  }
  nav .nav-list {
    gap: var(--spacing-sm);
  }
  section {
    padding-top: var(--spacing-lg);
    padding-bottom: var(--spacing-lg);
  }
  .grid {
    gap: var(--spacing-md);
  }
}

/* Desktop breakpoint */
@media (min-width: 601px) {
  .grid-2 { grid-template-columns: repeat(2, 1fr); }
  .grid-3 { grid-template-columns: repeat(3, 1fr); }
  .grid-4 { grid-template-columns: repeat(4, 1fr); }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  * { animation: none !important; transition: none !important; }
}

