.index-hero { background-color: var(--color-dark-bg); color: var(--color-accent-on-dark); text-align: center; }
.index-hero-inner { display: flex; flex-direction: column; align-items: center; gap: var(--spacing-md); padding-top: var(--spacing-xl); padding-bottom: var(--spacing-xl); }
.index-hero h1 { color: var(--color-accent-on-dark); font-size: clamp(1.75rem, 4vw, 2.75rem); max-width: 45rem; }
.index-hero-lede { max-width: 38rem; font-size: 1.1rem; color: var(--color-accent-on-dark); }

.index-about-inner { display: grid; gap: var(--spacing-lg); grid-template-columns: 1fr; align-items: center; }
.index-about-img { border-radius: var(--radius); width: 100%; height: auto; object-fit: cover; }

.index-gallery-grid img { width: 100%; height: 14rem; object-fit: cover; border-radius: var(--radius); }

.index-service-card { text-align: center; }
.index-service-price { font-size: 1.4rem; font-weight: bold; color: var(--color-accent-dark); margin-bottom: var(--spacing-sm); }

.index-quote { font-style: italic; }
.index-quote footer { margin-top: var(--spacing-md); font-style: normal; font-weight: bold; color: var(--color-text-muted); }

.index-contact-inner { display: grid; gap: var(--spacing-lg); grid-template-columns: 1fr; }
.index-contact-list { list-style: none; padding: 0; margin: 0 0 var(--spacing-md) 0; }
.index-contact-list li { margin-bottom: 0.35rem; }
.index-hours { border-collapse: collapse; width: 100%; max-width: 28rem; }
.index-hours th, .index-hours td { text-align: left; padding: 0.4rem 0.6rem; border-bottom: 1px solid var(--color-border); font-weight: normal; }
.index-hours th { font-weight: bold; }

@media (min-width: 601px) {
  .index-about-inner { grid-template-columns: 3fr 2fr; }
  .index-contact-inner { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 600px) {
  .index-gallery-grid img { height: 11rem; }
  .index-hero-inner { padding-top: var(--spacing-lg); padding-bottom: var(--spacing-lg); }
}

